# Nested archive traversal: recursive container tree with depth cap and cycle guard.
tree = {'outer': {'inner': {'deep.txt': None}, 'a.txt': None}}
def walk(node, depth=0, max_depth=5, seen=None):
    seen = seen or set()
    indent = "  " * depth
    for name, sub in sorted(node.items()):
        is_arc = isinstance(sub, dict)
        print(f"{indent}{name}{'/' if is_arc else ''}")
        if is_arc and depth < max_depth and id(sub) not in seen:
            seen.add(id(sub))
            walk(sub, depth + 1, max_depth, seen)
print("nested traversal (depth cap 5):")
walk(tree)

